31|        return { success: false, error: 'Main window not initialized' };
32|      }
33|
34|      if (!forceRefresh && this.currentToken && this.tokenExpiry) {
35|        const now = Date.now();
36|        const expiryTime = new Date(this.tokenExpiry).getTime();
37|        const timeUntilExpiry = expiryTime - now;
38|
39|        // Require 5-minute buffer before expiry to avoid race conditions
40|        if (timeUntilExpiry > 5 * 60 * 1000) {
41|          logger.debug('[GRAPH_API] Using cached token', {
42|            timeUntilExpiry: Math.floor(timeUntilExpiry / 1000) + 's'
43|          });
44|          return {
45|            success: true,
46|            token: this.currentToken,
47|            fromCache: true,
48|            expiry: this.tokenExpiry
49|          };
50|        }
51|      }
52|
53|      const result = await this.mainWindow.webContents.executeJavaScript(`
54|        (async () => {
55|          if (window.teamsForLinuxReactHandler && typeof window.teamsForLinuxReactHandler.acquireToken === 'function') {
56|            return await window.teamsForLinuxReactHandler.acquireToken('https://graph.microsoft.com', {
57|              forceRenew: ${forceRefresh}
58|            });
59|          } else {
60|            return { success: false, error: 'ReactHandler not available' };
61|          }
62|        })()
63|      `);
64|
65|      if (result?.success && result?.token) {
66|        this.currentToken = result.token;
67|        this.tokenExpiry = result.expiry;
68|
69|        logger.debug('[GRAPH_API] Token acquired successfully', {
70|          fromCache: result.fromCache,
71|          expiry: result.expiry
72|        });
73|
74|        return result;
75|      } else {
76|        logger.warn('[GRAPH_API] Token acquisition failed', result);
77|        return result || { success: false, error: 'Unknown error' };
78|      }
79|
80|    } catch (error) {
81|      logger.error('[GRAPH_API] Token acquisition error:', error);
82|      return {
83|        success: false,
84|        error: error.message || error.toString()
85|      };
