89|  async makeRequest(endpoint, options = {}) {
90|    try {
91|      if (!this.enabled) {
92|        logger.warn('[GRAPH_API] Graph API is disabled');
93|        return { success: false, error: 'Graph API is disabled' };
94|      }
95|
96|      const tokenResult = await this.acquireToken();
97|      if (!tokenResult.success || !tokenResult.token) {
98|        return { success: false, error: 'Failed to acquire token' };
99|      }
100|
101|      const url = endpoint.startsWith('http') ? endpoint : `${this.baseUrl}${endpoint}`;
102|      const method = options.method || 'GET';
103|
104|      logger.debug('[GRAPH_API] Making request', { method, endpoint: url });
105|
106|      const response = await fetch(url, {
107|        method,
108|        headers: {
109|          'Authorization': `Bearer ${tokenResult.token}`,
110|          'Content-Type': 'application/json',
111|          ...options.headers
112|        },
113|        ...(options.body && { body: JSON.stringify(options.body) })
114|      });
