124|            status: response.status,
125|            textPreview: responseText.substring(0, 100),
126|            parseError: parseError.message
127|          });
128|        }
129|      }
130|
131|      if (response.ok) {
132|        logger.debug('[GRAPH_API] Request successful', {
133|          status: response.status,
134|          endpoint: url
135|        });
136|        return { success: true, data };
137|      } else {
138|        logger.warn('[GRAPH_API] Request failed', {
139|          status: response.status,
140|          error: data?.error
141|        });
142|        return {
143|          success: false,
144|          error: data?.error?.message || responseText || 'API request failed',
145|          status: response.status,
146|          data
147|        };
148|      }
149|
