70|    if (!graphApiClient) return notEnabled;
71|    try {
72|      return await graphApiClient.searchPeople(query, options);
73|    } catch (error) {
74|      logger.error('[GRAPH_API] searchPeople failed:', { message: error.message });
75|      return { success: false, error: error.message };
